import {listTierlists,manageTierlist,likeTierlist} from './tierlist-api.mjs';
import {cleanList} from './tierlist-model.mjs';import {drawTierlist} from './tierlist-render.mjs';
const $=id=>document.getElementById(id),el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n};let mine=new URL(location.href).searchParams.get('view')==='mine',records=[],units=[],generation=0;
const status=s=>$('library-status').textContent=s;
const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){observer.unobserve(e.target);e.target.render?.()}},{rootMargin:'100px'});
async function load(){const token=++generation;$('mine-view').setAttribute('aria-pressed',String(mine));$('public-view').setAttribute('aria-pressed',String(!mine));status('Loading tierlists…');try{const loaded=await listTierlists(mine);if(token!==generation)return;records=loaded;render();status(records.length+' tierlists.')}catch(e){if(token!==generation)return;records=[];render();status(e.message)}}
function render(){observer.disconnect();const list=$('tierlist-library'),q=$('library-search').value.toLowerCase(),shown=records.filter(r=>(!$('library-mode').value||r.payload.gameMode===$('library-mode').value)&&(!q||(r.name+' '+(r.payload.shareAuthor||'')).toLowerCase().includes(q)));if($('library-sort').value==='likes')shown.sort((a,b)=>(b.likes||0)-(a.likes||0));list.replaceChildren();if(!shown.length){list.append(el('p',mine?'Your saved tierlists will appear here.':'Published community tierlists will appear here.'));return}for(const r of shown){const card=el('article',undefined,'maker-panel tierlist-entry'),canvas=el('canvas');canvas.setAttribute('aria-label',r.name+' ranking preview');canvas.render=()=>drawTierlist(canvas,cleanList(r.payload,units),units).catch(e=>status(e.message));observer.observe(canvas);card.append(canvas,el('h2',r.name),el('p',r.payload.gameMode+' · Tier '+r.payload.tier+(r.payload.shareAuthor?' · '+r.payload.shareAuthor:'')));if(r.payload.notes)card.append(el('p',r.payload.notes));const actions=el('div',undefined,'maker-actions'),open=el('a',mine?'Edit draft':'Open','btn secondary');open.href=new URL('./drafter/tierlist.html',import.meta.url).href+'?tierlist='+encodeURIComponent(r.id)+(mine?'&private=1':'');actions.append(open);if(!mine){const like=el('button','Like '+(r.likes||0),'btn secondary');like.setAttribute('aria-pressed',String(!!r.liked));like.onclick=async()=>{like.disabled=true;try{const result=await likeTierlist(r.id);r.likes=result.likes;r.liked=result.liked;like.textContent='Like '+result.likes;like.setAttribute('aria-pressed',String(result.liked))}catch(e){status(e.message)}finally{like.disabled=false}};actions.append(like)}else{card.append(el('p',r.published?'Private draft + published snapshot':'Private draft'));for(const action of [...(r.published?['unpublish']:[]),'delete']){const b=el('button',action==='delete'?'Delete':'Unpublish','btn secondary');b.onclick=async()=>{if(!confirm(action==='delete'?'Delete this tierlist and its public version?':'Unpublish this tierlist? Your private draft remains.'))return;b.disabled=true;try{await manageTierlist(r.id,r.revision,action);await load()}catch(e){status(e.message);b.disabled=false}};actions.append(b)}}card.append(actions);list.append(card)}}
$('public-view').onclick=()=>{mine=false;load()};$('mine-view').onclick=()=>{mine=true;load()};$('refresh').onclick=load;$('library-search').oninput=render;$('library-mode').onchange=render;$('library-sort').onchange=render;
try{const r=await fetch(new URL('./tatari-data/roster.json',import.meta.url));if(!r.ok)throw Error('Tatari data unavailable.');units=(await r.json()).units;await load()}catch(e){status(e.message)}
